def calc_cagr(start, end, years):
    if start and end and years > 0 and start != 0:
        try:
            s, e = float(start), float(end)
            if s > 0 and e > 0:
                return (pow(e / s, 1 / years) - 1) * 100
        except:
            pass
    return None


