    nm = to_float(net_margin[li])
    r = to_float(roe[li])
    if gm:
        lines.append(f"毛利率{gm:.1f}%，{'处于高毛利水平，产品竞争力强' if gm > 70 else '毛利率良好' if gm > 40 else '毛利率偏低，需关注成本控制'}。")
    if r:
        lines.append(f"ROE为{r:.1f}%，{'盈利能力优秀' if r > 15 else '回报水平合理' if r > 0 else '尚未实现正向股东回报'}。")

    # Forecast hint
